#!/usr/bin/env python3
"""Validation module for the LAB programming basics, week 5 task 2."""


import random


# ------------------------- ALOITA TEHTÄVÄN TOTEUTUS TÄSTÄ ---------------------------- #

def is_divisible(a, b):
    """Tarkistaa, onko luku 'a' jaollinen luvulla 'b'."""
    if b == 0:
        return False
    return a % b == 0


def is_prime(n):
    """Tarkistaa, onko luku 'n' alkuluku."""
    if n <= 1:
        return False

    i = 2
    while i * i <= n:
        if is_divisible(n, i):
            return False
        i += 1

    return True

# ----------------------- TEHTÄVÄN TOTEUTUS ENNEN TÄTÄ RIVIÄ -------------------------- #

# Tarkistuskoodi alkaa

def validate_is_divisible():
    """Check that the is_divisible function returns correct values."""
    try:
        # Tarkistetaan funktio satunnaisilla arvoilla kymmenen kertaa
        for _ in range(0, 10):
            x = random.randint(1, 100)
            y = random.randint(1, 100)
            v = is_divisible(x, y)
            if v != x % y == 0:
                print("Funktio is_divisible on toteutettu väärin.")
                print(f"Haluttiin arvo {x % y == 0}, saatiin arvo {v}.")
                return False

        # Tarkistetaan ainakin yksi varmuudella jaollinen tapaus
        y = random.randint(2, 10)
        x = random.choice(list(range(y, y * 1000, y)))
        v = is_divisible(x, y)
        if not v:
            print("Funktio is_divisible on toteutettu väärin.")
            print("Luku {x} on jaollinen luvulla {y}.")
            return False

        # Tarkistetaan reunatapaus nollalla jakaminen
        x = random.randint(1, 100)
        y = 0
        try:
            if is_divisible(x, y):
                print("Funktio is_divisible on toteutettu väärin.")
                print("Funktion tulee palauttaa False yritettäessä jakaa nollalla.")
                return False
        except ZeroDivisionError:
            print("Funktio is_divisible on toteutettu väärin.")
            print("Funktio ei palauta False yrittäessä jakaa nollalla.")
            return False

        print("Funktio is_divisible on toteutettu oikein.")
    except NameError:
        print("Funktio is_divisible ei ole vielä määritelty.")
        return False

    return True


